import{_ as a,o as n,c as s,a0 as c}from"./chunks/framework.DCluYYrN.js";const _=JSON.parse('{"title":"x86_64 支持","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/guide/x86_64-support.md","filePath":"zh_CN/guide/x86_64-support.md"}'),l={name:"zh_CN/guide/x86_64-support.md"};function o(t,e,p,i,r,d){return n(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="x86-64-支持" tabindex="-1">x86_64 支持 <a class="header-anchor" href="#x86-64-支持" aria-label="Permalink to &quot;x86_64 支持&quot;">​</a></h1><p>KernelSU 完全支持 <code>x86_64</code> 架构。但由于上游内核近期的安全改动，在较新的 <code>x86_64</code> 内核上集成 KernelSU 时，需要额外处理，才能让统一的 syscall dispatcher 正常工作。</p><h2 id="为什么会失效" tabindex="-1">为什么会失效？ <a class="header-anchor" href="#为什么会失效" aria-label="Permalink to &quot;为什么会失效？&quot;">​</a></h2><p>在较新的内核版本中，引入了一个 <a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/commit/?id=1e3ad78334a69b36e107232e337f9d693dcc9df2" target="_blank" rel="noreferrer">提交</a> 来加固 syscall table。这个改动把系统调用路径中的间接跳转转换成了一系列直接条件分支。</p><p>KernelSU 的 <code>syscall_hook</code> 机制依赖对系统调用表的修改，从而把被拦截的系统调用路由到统一 dispatcher。由于新的加固机制改变了系统调用路径，内核会忽略这些对系统调用表的修改。若 KernelSU 在没有正确处理该限制的情况下加载并 hook syscall table，将无法正确路由调用，并会主动中止初始化，以避免内核 panic。</p><h2 id="如何修复" tabindex="-1">如何修复？ <a class="header-anchor" href="#如何修复" aria-label="Permalink to &quot;如何修复？&quot;">​</a></h2><p>现在有两种受支持的方式来处理 <code>x86_64</code> 上的 syscall hook 问题：</p><ol><li>启用内核编译选项 <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>。</li><li>继续使用原有的内核源码补丁方案。</li></ol><p>二选一即可，不要同时使用两种方案。</p><h3 id="方案-1-启用-ksu-x86-patch-syscall-dispatcher" tabindex="-1">方案 1：启用 <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> <a class="header-anchor" href="#方案-1-启用-ksu-x86-patch-syscall-dispatcher" aria-label="Permalink to &quot;方案 1：启用 \`KSU_X86_PATCH_SYSCALL_DISPATCHER\`&quot;">​</a></h3><p>KernelSU 3.3.0 为 <code>x86_64</code> 新增了官方机制，即编译选项 <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>。</p><p>启用后，KernelSU 会在运行时动态 patch 已加固的 syscall dispatcher，使 syscall hook 可以正常工作，而不再依赖之前那组内核源码补丁。如果你使用的是 KernelSU 3.3.0 或更新版本，并且可以调整 KernelSU 的构建配置，建议优先采用这种方式。</p><h3 id="方案-2-应用原有的内核源码补丁" tabindex="-1">方案 2：应用原有的内核源码补丁 <a class="header-anchor" href="#方案-2-应用原有的内核源码补丁" aria-label="Permalink to &quot;方案 2：应用原有的内核源码补丁&quot;">​</a></h3><p>如果你不想启用 <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>，也可以继续沿用原有的内核补丁方案。</p><p>要让 KernelSU 在这些较新的内核上工作，需要应用补丁以绕过这项 syscall 加固。</p><div class="danger custom-block"><p class="custom-block-title">安全警告</p><p>使用这两种方案中的任意一种，都意味着你在主动绕过或削弱一项用于防御推测执行漏洞的缓解措施。</p><p>这会重新暴露系统调用路径中的间接分支攻击面。<strong>如果你的环境是生产服务器，或者对侧信道安全有严格要求，请不要使用这两种方案。</strong> 这些方案仅适用于测试环境，前提是你更重视通过 KernelSU 获得 root 能力，而不是这项特定硬件漏洞缓解。</p></div><p>请根据你的内核版本选择并应用下面对应的补丁。这些补丁会创建一个名为 <code>X86_FEATURE_INDIRECT_SAFE</code> 的特性，并可通过内核命令行参数 <code>syscall_hardening=off</code> 启用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For kernel 6.6:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/fe9a9b4c320577c30e1f22d04039e414c6a3cdec</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/df772e99e392f24b395ceaf7b26974e3e4828ee9</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.12:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/dd2c602268fdc81f4d3b662f6a15142ac0ec7bcd</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/7d99237ae5da61c19447138da3282ae37d43857b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.18:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/40b1c323d1ad29c86e041d665c7f089b9a3ccfb5</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/f5813e10b7630e1ccd86fc2c4cf30eef60b64a82</span></span></code></pre></div><h2 id="应该选择哪种方案" tabindex="-1">应该选择哪种方案？ <a class="header-anchor" href="#应该选择哪种方案" aria-label="Permalink to &quot;应该选择哪种方案？&quot;">​</a></h2><ul><li>如果你使用的是 KernelSU 3.3.0 或更新版本，且可以修改 KernelSU 构建配置，建议启用 <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>。</li><li>如果你希望继续保持现有的内核补丁工作流，则继续使用上面的源码补丁方案。</li></ul>`,20)])])}const m=a(l,[["render",o]]);export{_ as __pageData,m as default};
